create table public.hydration_groups(id uuid primary key default gen_random_uuid(), title text not null check(length(title) between 1 and 80), invite_code uuid unique not null default gen_random_uuid(), owner_id uuid not null references auth.users(id));
create table public.hydration_members(group_id uuid references public.hydration_groups(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,display_name text not null check(length(display_name) between 1 and 40),goal_oz numeric not null default 64 check(goal_oz > 0 and goal_oz <= 256),primary key(group_id,user_id));
create table public.hydration_daily(group_id uuid not null,user_id uuid not null,day date not null,oz numeric not null check(oz>=0 and oz<=512),primary key(group_id,user_id,day),foreign key(group_id,user_id) references public.hydration_members(group_id,user_id) on delete cascade);
alter table public.hydration_groups enable row level security;
alter table public.hydration_members enable row level security;
alter table public.hydration_daily enable row level security;
create function iron_private.hydration_member(g uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.hydration_members where group_id=g and user_id=auth.uid()) $$;
create policy group_read on public.hydration_groups for select to authenticated using(iron_private.hydration_member(id));
create policy member_read on public.hydration_members for select to authenticated using(iron_private.hydration_member(group_id));
create policy member_goal on public.hydration_members for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy water_read on public.hydration_daily for select to authenticated using(iron_private.hydration_member(group_id));
create policy water_insert on public.hydration_daily for insert to authenticated with check(user_id=auth.uid() and iron_private.hydration_member(group_id));
create policy water_update on public.hydration_daily for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and iron_private.hydration_member(group_id));
create function iron_private.hydration_create(t text,n text) returns uuid language plpgsql security definer set search_path='' as $$ declare g uuid; begin if auth.uid() is null then raise exception 'Join first'; end if; insert into public.hydration_groups(title,owner_id) values(t,auth.uid()) returning id into g; insert into public.hydration_members(group_id,user_id,display_name) values(g,auth.uid(),n); return g; end $$;
create function iron_private.hydration_join(c uuid,n text) returns uuid language plpgsql security definer set search_path='' as $$ declare g uuid; begin if auth.uid() is null then raise exception 'Join first'; end if; select id into g from public.hydration_groups where invite_code=c; if g is null then raise exception 'Invalid invite'; end if; insert into public.hydration_members(group_id,user_id,display_name) values(g,auth.uid(),n) on conflict do nothing; return g; end $$;
create function public.hydration_create(t text,n text) returns uuid language sql security invoker set search_path='' as $$ select iron_private.hydration_create(t,n) $$;
create function public.hydration_join(c uuid,n text) returns uuid language sql security invoker set search_path='' as $$ select iron_private.hydration_join(c,n) $$;
revoke all on function iron_private.hydration_member(uuid),iron_private.hydration_create(text,text),iron_private.hydration_join(uuid,text),public.hydration_create(text,text),public.hydration_join(uuid,text) from public,anon;
grant execute on function iron_private.hydration_member(uuid),iron_private.hydration_create(text,text),iron_private.hydration_join(uuid,text),public.hydration_create(text,text),public.hydration_join(uuid,text) to authenticated;
revoke all on public.hydration_groups,public.hydration_members,public.hydration_daily from anon,authenticated;
grant select on public.hydration_groups,public.hydration_members,public.hydration_daily to authenticated;
grant update(goal_oz) on public.hydration_members to authenticated;
grant insert,update on public.hydration_daily to authenticated;